// orders · кейсы ord-01, ord-04, ord-05, ord-06, ord-07 (.qa/tests/orders/) — רשימת הזמנות (מפיץ), только чтение
import { test, expect, Page } from '@playwright/test';
import * as path from 'path';

test.use({ storageState: path.resolve(__dirname, '../../../auth/admin.json') });

const rows = (page: Page) => page.getByRole('button', { name: /^#\d+ / });
const shown = (page: Page) => page.getByText(/^מציג \d+–\d+ מתוך \d+ תוצאות$/);

async function openOrders(page: Page) {
  await page.goto('/orders');
  await expect(page.getByRole('heading', { level: 1, name: 'הזמנות' })).toBeVisible();
  await page.getByRole('combobox', { name: 'סינון לפי חודש' }).selectOption({ label: 'כל החודשים' });
  await expect(rows(page).first()).toBeVisible({ timeout: 20_000 });
}

test.describe('orders — רשימת הזמנות', () => {
  test('לשוניות הסטטוס מימין, «הכל» ראשון; כפתורי הפעולה העליונים אחידים #6a859021 @desktop @prod-safe', async ({ page }) => {
    await openOrders(page);
    const h1 = await page.getByRole('heading', { level: 1, name: 'הזמנות' }).boundingBox();
    const all = await page.getByRole('button', { name: /^הכל \d+$/ }).boundingBox();
    const pending = await page.getByRole('button', { name: /^ממתינות לאישור \d+$/ }).boundingBox();
    expect(Math.abs(all!.x + all!.width - (h1!.x + h1!.width))).toBeLessThanOrEqual(2);
    expect(all!.x).toBeGreaterThan(pending!.x);

    const controls = [
      page.getByRole('button', { name: 'החזרות' }),
      page.getByRole('button', { name: 'הזמנה מהודעה' }),
      page.getByRole('button', { name: 'מכירה מיידית' }),
      page.getByRole('combobox', { name: 'סינון לפי חודש' }),
    ];
    for (const c of controls) {
      const st = await c.evaluate((e) => {
        const s = getComputedStyle(e);
        return { h: Math.round(e.getBoundingClientRect().height), bg: s.backgroundColor, bw: s.borderTopWidth, bc: s.borderTopColor, r: s.borderTopLeftRadius, fs: s.fontSize, fw: s.fontWeight };
      });
      expect(st).toEqual({ h: 44, bg: 'rgb(255, 255, 255)', bw: '1px', bc: 'rgb(231, 233, 238)', r: '8px', fs: '14px', fw: '500' });
    }
  });

  test('עימוד: חיצי «העמוד הקודם»/«העמוד הבא» משני צדי המספרים #6a6755e0 @desktop @prod-safe', async ({ page }) => {
    await openOrders(page);
    const total = Number((await shown(page).innerText()).match(/מתוך (\d+)/)![1]);
    test.skip(total <= 8, 'нужно больше 8 заказов');
    await expect(shown(page)).toHaveText(`מציג 1–8 מתוך ${total} תוצאות`);
    const prev = page.getByRole('button', { name: 'העמוד הקודם' });
    const next = page.getByRole('button', { name: 'העמוד הבא' });
    await expect(prev).toBeDisabled();
    await expect(page.getByRole('button', { name: '1', exact: true })).toBeVisible();
    await expect(page.getByRole('button', { name: '2', exact: true })).toBeVisible();
    await next.click();
    await expect(shown(page)).toHaveText(new RegExp(`^מציג 9–\\d+ מתוך ${total} תוצאות$`));
    await expect(prev).toBeEnabled();
    await prev.click();
    await expect(shown(page)).toHaveText(`מציג 1–8 מתוך ${total} תוצאות`);
  });

  test('סינון לפי שלב + סטטוס תשלום, מצב ריק עם «איפוס סינון» #6a38cf5c @desktop @prod-safe', async ({ page }) => {
    await page.goto('/orders');
    await expect(page.getByRole('heading', { level: 1, name: 'הזמנות' })).toBeVisible();
    const monthSel = page.getByRole('combobox', { name: 'סינון לפי חודש' });
    await expect(shown(page)).toBeVisible({ timeout: 20_000 });
    const monthCounter = await shown(page).innerText(); // המונה של החודש הנוכחי
    await monthSel.selectOption({ label: 'כל החודשים' });
    await expect(rows(page).first()).toBeVisible({ timeout: 20_000 });
    // ממתינים שהמונה ישתנה מזה של החודש הנוכחי (אם יש הבדל) ורק אז קוראים את before
    await expect.poll(async () => shown(page).innerText(), { timeout: 10_000 }).not.toBe(monthCounter).catch(() => {});
    let before = await shown(page).innerText();
    await expect.poll(async () => {
      const cur = await shown(page).innerText();
      const stable = cur === before;
      before = cur;
      return stable;
    }, { intervals: [500], timeout: 10_000 }).toBe(true);
    await page.getByRole('button', { name: 'סינון' }).click();
    await expect(page.getByRole('heading', { name: 'סינון הזמנות' })).toBeVisible();
    for (const f of ['סטטוס תשלום', 'שלב ההזמנה', 'לקוח', 'תאריך']) await expect(page.getByRole('combobox', { name: f })).toBeVisible();

    await page.getByRole('combobox', { name: 'שלב ההזמנה' }).selectOption({ label: 'בליקוט במחסן' });
    await expect(page.getByRole('button', { name: 'סינון 1' })).toBeVisible();
    await expect(page.getByRole('button', { name: 'ניקוי סינון' })).toBeVisible();
    const n1 = await rows(page).count();
    for (let i = 0; i < n1; i++) await expect(rows(page).nth(i)).toHaveAccessibleName(/בליקוט במחסן/);

    await page.getByRole('combobox', { name: 'סטטוס תשלום' }).selectOption({ label: 'שולם חלקית' });
    await expect(page.getByRole('button', { name: 'סינון 2' })).toBeVisible();
    const n2 = await rows(page).count();
    for (let i = 0; i < n2; i++) await expect(rows(page).nth(i)).toHaveAccessibleName(/שולם חלקית.*בליקוט במחסן/);

    // Отклонённый и оплаченный заказ — комбинация без результатов.
    await page.getByRole('combobox', { name: 'שלב ההזמנה' }).selectOption({ label: 'נדחתה' });
    await page.getByRole('combobox', { name: 'סטטוס תשלום' }).selectOption({ label: 'שולם' });
    await expect(page.getByText('לא נמצאו הזמנות התואמות לסינון')).toBeVisible();
    await expect(page.getByText('נסה לשנות את הסינון או לאפס אותו.')).toBeVisible();
    await expect(rows(page)).toHaveCount(0);
    await page.getByRole('button', { name: 'איפוס סינון' }).click();
    await expect(shown(page)).toHaveText(before);
  });

  test('מיון: «תאריך — מהישן לחדש» מסדר את התאריכים בסדר עולה #6a38cf5c @desktop @prod-safe', async ({ page }) => {
    await openOrders(page);
    await page.getByRole('button', { name: 'מיון' }).click();
    await expect(page.getByRole('heading', { name: 'מיון הזמנות' })).toBeVisible();
    await expect(page.getByRole('button', { name: 'תאריך — מהחדש לישן' })).toHaveAttribute('aria-pressed', 'true');
    for (const s of ['סכום — מהגבוה לנמוך', 'סכום — מהנמוך לגבוה', 'לקוח — א׳ עד ת׳']) await expect(page.getByRole('button', { name: s })).toBeVisible();
    const asc = page.getByRole('button', { name: 'תאריך — מהישן לחדש' });
    await asc.click();
    await expect(asc).toHaveAttribute('aria-pressed', 'true');
    await page.waitForTimeout(800);
    const names = await rows(page).evaluateAll((els) => els.map((e) => e.textContent || ''));
    const dates = names.map((n) => {
      const [d, m, y] = n.match(/(\d{2})\.(\d{2})\.(\d{4})/)!.slice(1).map(Number);
      return y * 10000 + m * 100 + d;
    });
    expect(dates.length).toBeGreaterThan(1);
    expect(dates).toEqual([...dates].sort((a, b) => a - b));
  });

  test('כשל טעינה (500): שגיאה עם «נסה שוב» תוך שניות, בלי מונים 0 ומצב ריק שקרי #6a6755e0 #6a677c6b #6a38cf5f #59d59e6f @desktop @prod-safe', async ({ page }) => {
    await page.route('**/rest/v1/orders?*', (r) => r.fulfill({ status: 500, contentType: 'application/json', body: '{"message":"QA simulated"}' }));
    const t0 = Date.now();
    await page.goto('/orders');
    await expect(page.getByText('אירעה שגיאה בטעינת ההזמנות. נסה שוב.')).toBeVisible({ timeout: 10_000 });
    await expect(page.getByText(/נסו שוב/)).toHaveCount(0); // #59d59e6f: ед. ч.
    expect(Date.now() - t0).toBeLessThan(10_000);
    await expect(page.getByRole('button', { name: 'נסה שוב' })).toBeVisible();
    await expect(page.getByRole('button', { name: /^הכל \d+$/ })).toHaveCount(0);
    await expect(page.getByText('אין הזמנות נכנסות')).toHaveCount(0);
    await page.unroute('**/rest/v1/orders?*');
    await page.getByRole('button', { name: 'נסה שוב' }).click();
    await expect(page.getByRole('button', { name: /^הכל \d+$/ })).toBeVisible({ timeout: 20_000 });
  });
});
